const uiText = (lang, key, vars = {}) => {
  const table = I18N[lang] || I18N.en;
  const fallback = I18N.en[key] || key;
  let out = table[key] || fallback;
  Object.keys(vars).forEach(k => {
    out = out.replaceAll(`{${k}}`, String(vars[k]));
  });
  return out;
};
const getCategoryLabel = (cat, lang) => {
  if (!cat) return '—';
  const jaCategories = {
    symmetric: '対称鍵',
    asymmetric: '非対称鍵',
    hashes: 'ハッシュダイジェスト',
    passwords: 'パスワードとフレーズ',
    kdf: 'KDFとパスワードハッシュ',
    macs: 'MACと認証子',
    identifiers: '識別子',
    tokens: 'トークンと認証',
    pq: 'ポスト量子'
  };
  if (lang === 'ja' && jaCategories[cat.id]) return jaCategories[cat.id];
  return CATEGORY_I18N[cat.id]?.[lang] || CATEGORY_I18N[cat.id]?.en || cat.label || cat.id;
};
