      gateway: inputRecord.gatewayChannel,
      target: 'phone-gateway',
      action: 'CONTROL_DISPATCH',
      nonce,
      digest: controlDigest,
      matchedCode: inputRecord.matchedCode,
      codeValue: inputRecord.matchedCode?.value || '',
