const buildMountainRecord = async (toolKey, {
  subject,
  note,
  sourceRows = [],
  file = null
}) => {
  const now = new Date().toISOString();
  const sourceValue = sourceRows[0]?.value || '';
  const fileBytes = file ? `${file.name}|${file.size}|${file.type}|${file.lastModified}` : '';
  const base = [toolKey, subject, note, sourceValue, fileBytes, now, mountainRand(18)].join('|');
  const hash = (await digestHex(base)).toUpperCase();
  const short = hash.slice(0, 18);
  if (toolKey === 'tokenVault') {
    return {
      id: `TVP-${short}`,
      type: 'TOKEN',
      subject,
      note,
      status: 'ACTIVE',
      version: 1,
      token: `ocg_tok_${hash.slice(0, 32)}`,
      source: sourceRows[0]?.typeId || sourceRows[0]?.type || 'manual',
      hash,
      createdAt: now
    };
  }
  if (toolKey === 'licenseIssuer') {
    return {
      id: `LIC-${short}`,
      type: 'LICENSE',
      subject,
      note,
      plan: 'Professional',
      status: 'ISSUED',
      expiresAt: new Date(Date.now() + 1000 * 60 * 60 * 24 * 365).toISOString(),
      licenseKey: `OCG-LIC-${hash.slice(0, 6)}-${hash.slice(6, 12)}-${hash.slice(12, 18)}`,
      hash,
      createdAt: now
    };
  }
  if (toolKey === 'chainLedger') {
    return {
      id: `LEDGER-${short}`,
      type: 'CHAIN',
      subject,
      note,
      index: Date.now(),
      prevHash: sourceRows[0]?.value ? (await digestHex(sourceRows[0].value)).toUpperCase() : 'GENESIS',
      hash,
      createdAt: now
    };
  }
  if (toolKey === 'apiKeyManager') {
    return {
      id: `API-${short}`,
      type: 'API_KEY',
      subject,
      note,
      status: 'ACTIVE',
      scopes: ['read:codes', 'write:vault', 'export:qr'],
      apiKey: `ocg_live_${hash.slice(0, 40)}`,
      hash,
      createdAt: now
    };
  }
  return {
    id: `TOKZ-${short}`,
    type: 'TOKENIZED_PACKAGE',
    subject: file?.name || subject,
    note,
    fileName: file?.name || '',
    fileSize: file?.size || 0,
    mime: file?.type || 'text/plain',
    packageId: `ocgfmt_${hash.slice(0, 28)}`,
    hash,
    createdAt: now
  };
};
