const makeHashcodDocId = prefix => {
  const date = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  const tail = Math.random().toString(36).slice(2, 7).toUpperCase();
  return `HC-${prefix}-${date}-${tail}`;
};
const quoteDueDate = days => {
  const date = new Date();
  date.setDate(date.getDate() + Math.max(0, Number(days) || 0));
  return date.toISOString();
};
const BILLING_TIMER_RATE_USD = 0.05;
const BILLING_TIMER_BLOCK_SECONDS = 10;
const formatBillingTimer = ms => {
  const total = Math.max(0, Math.floor((Number(ms) || 0) / 1000));
  const h = Math.floor(total / 3600);
  const m = Math.floor(total % 3600 / 60);
  const s = total % 60;
  return [h, m, s].map(n => String(n).padStart(2, '0')).join(':');
};
const billingTimerMoney = elapsedMs => {
  const blocks = Math.floor(Math.max(0, Number(elapsedMs) || 0) / (BILLING_TIMER_BLOCK_SECONDS * 1000));
  return {
    blocks,
    amount: Number((blocks * BILLING_TIMER_RATE_USD).toFixed(2))
  };
};
const HASHCOD_CLIENT_VAULT_STORAGE = 'hashcod_client_credentials_v1';
const readClientVaultRecords = () => safeJsonParse(localStorage.getItem(HASHCOD_CLIENT_VAULT_STORAGE) || '[]', []);
